def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_prev_bids = []
    rich_aggressive = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_prev_bids.append(float(bid))
                if opp.get('budget', 0) > 300 and float(bid) >= 90:
                    rich_aggressive.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    contested = slots <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_urgent = max(urgent_prev_bids) if urgent_prev_bids else highest_prev
    rich_pressure = max(rich_aggressive) if rich_aggressive else 0.0

    danger = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    if danger:
        bid = max(72.0, min(118.0, highest_urgent + 2.5))
        if contested:
            bid = max(bid, 96.0)
        return float(min(budget, bid))

    if contested:
        if rich_pressure >= 110 and hp >= 5:
            bid = 24.0
        elif highest_prev >= 95:
            bid = 34.0 if hp >= 6 else 82.0
        elif highest_prev >= 60:
            bid = highest_prev + 2.0 if caution else highest_prev * 0.72
        else:
            bid = 52.0 if caution else 41.0
    else:
        if highest_prev >= 100:
            bid = 20.0 if hp >= 6 else 58.0
        elif highest_prev >= 70:
            bid = 33.0 if hp >= 5 else 54.0
        else:
            bid = 28.0 if hp >= 5 else 46.0

    if day >= 8 and hp <= 4:
        bid = max(bid, 78.0)
    elif day >= 9 and hp <= 6:
        bid = max(bid, 62.0)

    min_safe = 0.0
    if no_water_days >= 1:
        min_safe = 36.0
    if hp <= 3:
        min_safe = max(min_safe, 60.0)

    bid = max(bid, min_safe)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If we are already in critical health, bid aggressively to secure water.
    if hp <= 2 or no_water_days >= 2:
        bid = DAILY_SALARY * 0.85
        return float(min(budget, bid))

    # Read yesterday's pressure from opponents' bids.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If others were spending heavily yesterday, we can underbid slightly to conserve budget.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Heuristic thresholds: Cindy/David/Eric appear to spend ~100-130; Alex had lower avg.
        if highest_prev_bid >= DAILY_SALARY * 1.0:
            # Still bid enough to not be the weakest; scale with supply.
            # When supply is scarce, increase bid; when abundant, reduce.
            scarcity = (25.0 - supply) / 10.0  # supply in [15,25] => scarcity in [1,0]
            scarcity = max(0.0, min(1.0, scarcity))
            base = DAILY_SALARY * 0.55
            bid = base * (0.75 + 0.5 * scarcity)
            return float(min(budget, bid))
        else:
            # If overall bids were moderate, bid closer to the top.
            bid = min(budget, max(DAILY_SALARY * 0.45, highest_prev_bid * 0.85))
            return float(bid)

    # No opponent info: default moderate bid.
    bid = DAILY_SALARY * 0.5
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev_bid * 1.05
    else:
        bid = DAILY_SALARY * 0.4

    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 0.8)

    return float(min(my_status['budget'], max(bid, 5.0)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    # Determine base bid
    if hp <= 2:
        base_bid = min(budget, DAILY_SALARY * 0.95)
    elif no_water_days >= 1 or hp <= 4:
        base_bid = min(budget, DAILY_SALARY * 0.75)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.55)
    # Adjust based on opponents' yesterday highest bid
    max_prev_bid = 0
    for opp in opponents_status.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])
    # If they were very aggressive, stay moderate
    if max_prev_bid > DAILY_SALARY * 0.85:
        if hp > 4:
            base_bid = min(budget, DAILY_SALARY * 0.35)
        else:
            base_bid = min(budget, DAILY_SALARY * 0.7)
    # Ensure we don't go bust
    if budget < DAILY_SALARY * 0.3:
        base_bid = min(budget, DAILY_SALARY * 0.9)
    return float(int(base_bid))
